// Pre-release manual test roster: what a human verifies before a Myne release,
// and why a machine cannot verify it instead.
//
// THIS FILE IS DATA. It is read by `scripts/check-manual-test-roster.mjs`, which
// is both the gate over it and the generator of `docs/dev/manual-test-roster.md`,
// and by `scripts/manual-test-plan.mjs`, which turns it into a per-release plan
// for one client. Nothing here executes anything. Editing the projection instead
// of this file is the one edit that is never right: the projection is generated
// and byte-gated, and a hand-kept second copy of a roster is the exact drift the
// guard exists to stop.
//
// WHAT EARNS A PLACE. Only an observation a machine cannot honestly make. If a
// tauri-driver scenario, a Vitest spec or a script guard could assert it, the
// item is automation debt and belongs in `e2e/` or `scripts/`, not here. That
// rule is enforced rather than stated: `whyNotAutomated` has to NAME THE
// MECHANISM that blocks a driver: the runner OS, the WebView engine, a physical
// device, an OS event source, a hardware property, or a perceptual judgement
// carrying a stated pass condition. A reason that describes the difficulty
// instead ("hard to automate", "needs a human", "visual check") fails the guard
// rather than passing quietly. `see` is written for a tester with no context: an
// instruction plus the observation that decides pass or fail, with no question
// left for the author.
//
// EVERY ITEM IS A SHIP GATE. A failed item stops the tag. Passing one anyway takes
// a written override recorded against the entry in
// `scripts/manual-test-verified.json`, the same shape `/done` uses for a
// `/pr-review` NEEDS-CHANGES verdict, where the default is to stop and going on is
// a named act that lands in the record. That is also why an item that did not have
// to be here is worse than redundant: it is a permanent false gate on a single
// maintainer's release day.
//
// TIERS. `core` is exactly three things: failing means DATA LOSS, failing means a
// SECURITY OR PRIVACY BOUNDARY broke (plaintext leaving the device, a locked vault
// still readable, a phrase or key on screen or in a log, an egress with no user
// consent), or the item verifies the UPGRADE over a real vault from the previous
// release. Everything else is `standard`. Both tiers are MEANT to gate the ship, and
// `gatedTiers` in `scripts/manual-test-ratchet.json` records which ones do
// today: `core` alone, on seven of the eight clients. A `standard` item is
// walked and recorded and does not block a tag yet, so do not read this tier
// choice as "may be skipped" either way. The tier decides ordering and what a
// short day drops first; the ratchet decides what stops the tag, it may only
// widen, and the end state is the whole file blocking.
//
// `estimateMin` IS PER CLIENT, for one execution. An item naming macOS, Linux and
// Windows is three sittings, and every consumer multiplies by `clients.length`
// for that reason. Counting once per item is how a roster this size reads as
// affordable when it is not.
//
// THE DENOMINATOR IS CHECKED BOTH WAYS. Every file under `src/screens/` and
// `src/components/settings/` must be claimed by some entry's `paths` (or recorded
// in the guard's `NOT_A_SURFACE` with the reason it renders no surface), and every
// `e2e/*.e2e.ts` scenario must be named by some entry's `automatedBy`. So a
// surface ENTERING the tree fails here, which is the property a hand-written
// checklist can never have: it is right the day it is written and wrong two
// releases later with nothing reporting the drift.
//
// A path or scenario that no longer exists also fails, because a verdict about a
// deleted surface is a verdict about nothing.
//
// Counts live in the GENERATED projection rather than here, because a figure
// hand-written into the source of truth is the one nobody re-derives: this line
// read 374 items, 138 core and 156.8 hours while the file held 383, 146 and
// 163.7, so the projection `--emit` recomputes on every run was right and the
// authoritative-looking copy was wrong. `node scripts/check-manual-test-roster.mjs
// --check` prints all of them. What is worth stating here is the shape rather
// than the size: a meaningful number of entries carry no manual item at all and
// argue why in `exemptionReason`, which is a legitimate answer that still has to
// be made.

/** @typedef {"desktop-macos"|"desktop-linux"|"desktop-windows"|"web"|"ios"|"android"|"cli"|"clipper"} Client */

/**
 * @typedef {object} ManualItem
 * @property {string} see               instruction plus the observation that decides pass or fail
 * @property {string} whyNotAutomated   the mechanism that blocks a driver, never the difficulty
 * @property {Client[]} clients         a subset of the entry's own clients
 * @property {number} estimateMin       minutes for ONE execution on ONE client
 * @property {"core"|"standard"} tier
 */

/**
 * SAFETY RULES, and they bind every item below rather than any one of them. The
 * text a walker reads is `WALK_PREAMBLE` in `scripts/check-manual-test-roster.mjs`,
 * emitted verbatim into the generated projection AND into every per-release plan,
 * so there is one source rather than a copy per document. Three rules, and what
 * each one is for when you are writing an item:
 *
 * 1. **Egress or a real credential means a disposable vault.** Release testing
 *    that sends real note text to a model provider is production personal data
 *    used as test data, a purpose limitation and data minimisation problem the
 *    feature itself does not have (GDPR Art. 5(1)(b) and (c)), created by the
 *    absence of the sentence rather than by anything in the product. Same for a
 *    real recovery phrase: typed into a device with autocorrect on, or held in a
 *    password manager, it is one string that reconstructs the whole vault.
 * 2. **Destroying something means a machine and a vault you can afford to lose.**
 *    An uninstall, a factory reset, a Keystore wipe, a migration over a real
 *    container, a disk filled to ENOSPC, a hard power cut. Rule 1 does not reach
 *    any of those, which is how they were written without it. There is no
 *    server-side copy, so a vault lost on the release machine is lost.
 * 3. **No cloud device farms**, ever, for any client.
 *
 * Where an item's own hazard is specific, say it in the item as well: which
 * volume, which machine, which box not to tick. The preamble is the floor.
 *
 * @typedef {object} Entry
 * @property {string} id                dotted lowercase slug, unique
 * @property {string} title
 * @property {string[]} paths           repo-relative; a trailing slash claims the directory
 * @property {Client[]} clients
 * @property {string[]} automatedBy     scenarios and guards that already cover part of it
 * @property {ManualItem[]} manual
 * @property {string} exemptionReason   argued sentence when `manual` is empty, "" otherwise
 */

/** @type {readonly Entry[]} */
